beforeExample:
class Example {
    void process() {
        StringBuffer buffer = new StringBuffer(100);
        buffer.append("Hello");
        buffer.append("World");
        String result = buffer.toString();
        System.out.println(result);
    }

    void processWithEmptyConstructor() {
        StringBuffer sb = new StringBuffer();
        sb.append("A");
        String s = sb.toString();
        System.out.println(s);
    }
}

